recipe:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  console = builtins.storePath /nix/store/pnjczqfn5dd3799cqq76sbbx6q2k0qrv-aos-hub-console-dist-0.1.0;
  inputs = import (root + "/tests/build/_bazel-registry-native-inputs.nix") {inherit pkgs;};
  cargoSource = builtins.storePath /nix/store/xmk0yi5fp07cv9yfwvaclkb2qms76sdm-crucible-cargo-src;
  nativeLibraries = inputs.nativeLibraries ++ [pkgs.sqlite];
  nativeTools = inputs.nativeTools;
  cargoSetup =
    inputs.cargoSetup
    + ''
      export LIBSQLITE3_SYS_USE_PKG_CONFIG=1
      export AOS_HUB_CONSOLE_JS="${console}/hub-console.js"
      export AOS_HUB_CONSOLE_WASM="${console}/hub-console_bg.wasm"
      export AOS_HUB_CONSOLE_CSS="${console}/hub-console.css"
      export RUST_TEST_THREADS="$NIX_BUILD_CORES"
    '';
  testSource = pkgs.runCommand "aos-hub-native-real-console-test-source" {buildDeps = [pkgs.patch];} ''
    mkdir -p "$out"
    cp -R ${cargoSource}/. "$out/"
    chmod -R u+w "$out"
    cd "$out"
    patch --batch -p1 < ${./hub-native-real-console-response-limit.patch}
  '';
  tests = import (root + "/tests/build/_bazel-cargo-oracle.nix") {
    inherit pkgs nativeLibraries nativeTools cargoSetup;
    cargoSource = testSource;
    pname = "aos-bazel-hub-native-cargo-baseline";
    packages = ["aos-hub-native"];
  };
  production = pkgs.mkDerivation {
    pname = "aos-bazel-hub-native-postgres-production-cargo-baseline";
    version = "1";
    src = cargoSource;
    buildDeps = [pkgs.rust pkgs.sed] ++ nativeTools;
    runtimeDeps = nativeLibraries;
    sharedBuildCache = false;
    dontStrip = true;
    dontPatchELF = true;
    dontNukeRefs = true;
    phases = [
      {
        name = "compile";
        script = ''
          cp -R "$src" source
          chmod -R u+w source
          cd source
          export CARGO_HOME="$TMPDIR/cargo" CARGO_TARGET_DIR="$TMPDIR/target"
          mkdir -p "$CARGO_HOME" .cargo "$out"
          sed 's|@vendor@|${pkgs.aos.passthru.cargoDeps}|g' \
            ${pkgs.aos.passthru.cargoDeps}/.cargo/config.toml > .cargo/config.toml
          ${cargoSetup}
          cargo build --frozen --offline --manifest-path crates/Cargo.toml \
            -p aos-hub-native --features postgres --lib --bins \
            --jobs "$NIX_BUILD_CORES" --message-format=json > "$out/cargo-messages.jsonl"
        '';
      }
    ];
  };
in {
  builds = [tests production];
  inherit tests production;
}

test_response_limit_patch:
--- a/crates/hub/aos-hub-native/tests/console.rs
+++ b/crates/hub/aos-hub-native/tests/console.rs
@@ -21,6 +21,10 @@
 use tower::ServiceExt as _;

 const TEST_JWT_SECRET: &[u8] = b"console-test-secret-32-byte-key!!";
+
+// The source-built console Wasm exceeds 1 MiB. This bounds collected test
+// responses independently of the production request-body limits.
+const MAX_TEST_RESPONSE_BYTES: usize = 16 * 1024 * 1024;

 fn removed_management_paths() -> Vec<String> {
     serde_json::from_str(include_str!("fixtures/removed-management-paths-v1.json"))
@@ -115,7 +119,7 @@
     let cache_control = header(header::CACHE_CONTROL);
     let content_type = header(header::CONTENT_TYPE);
     let content_security_policy = header(header::CONTENT_SECURITY_POLICY);
-    let body = axum::body::to_bytes(response.into_body(), 1 << 20)
+    let body = axum::body::to_bytes(response.into_body(), MAX_TEST_RESPONSE_BYTES)
         .await
         .unwrap()
         .to_vec();
